// ============================================================================
// AskMe AI + DeepSeek -> OpenAI-compatible gateway (Cloudflare Worker)
// ----------------------------------------------------------------------------
// Same API as askme-openai-gateway.mjs, but for a public HTTPS URL:
//
//   1. Paste this file as your Worker's code (or `npx wrangler deploy` it).
//   2. Optional vars: MODEL_ID=askme-ai, DS_MODEL_ID=deepseek, API_KEY=secret,
//      ASKME_ORIGIN=..., DS_ORIGIN=..., DEEPSEEK_TOKEN=your login userToken.
//   3. In 9Router add a custom OpenAI-compatible provider:
//        Base URL: https://<your-worker>.workers.dev/v1
//        Model:    askme-ai | deepseek     API key: <API_KEY or anything>
//
// DeepSeek login token: log in at https://chat.deepseek.com/ in your browser,
// devtools -> Application -> Local Storage -> chat.deepseek.com, copy the
// `userToken` value into the DEEPSEEK_TOKEN var. (It grants full account
// access: keep it secret, rotate by logging out if it ever leaks.)
//
// NOTE: DeepSeek mode solves a proof-of-work per request with DeepSeek's own
// bundled WASM solver (DS_WASM_B64 below, ~27KB). It needs ~0.5s of CPU per
// request, so on the Workers FREE plan (10ms CPU limit) DeepSeek mode will
// FAIL — use the local Node gateway for DeepSeek, or a paid Worker plan.
// AskMe mode works fine on the free plan.
//
// Endpoints: GET /v1/models, POST /v1/chat/completions (stream + non-stream),
// GET /healthz, GET /. Requests are stateless.
// ============================================================================

const APP_VERSION = "unknown";
const MAX_PROMPT_CHARS = 12000;
const ASKME_TIMEOUT_MS = 120000;
const DS_TIMEOUT_MS = 180000;

const BCG = [1, 2, 2, 4, 8, 32, 5, 160];
const AUW = [123, 47, 145, 68, 232, 60, 165, 105];
const AS0 = [210, 23, 142, 243, 86, 186, 13, 193];
const SUFFIXES = ["Zy3", "A7x", "Lp2", "Hj4", "K9m", "Qw8", "Xs1", "Nv7"];
const DS_TARGET_PATH = "/api/v0/chat/completion";
const DS_MODEL_TYPE = "deepseek-chat";

// ------------------------------- mapping -----------------------------------
function estimateTokens(text) {
  return Math.ceil(String(text || "").length / 4);
}

function extractTextContent(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    const parts = [];
    for (const p of content) {
      if (p && p.type === "text" && typeof p.text === "string") parts.push(p.text);
      else if (p && p.type === "image_url") parts.push("[image omitted: not supported by this bridge]");
    }
    return parts.join("\n");
  }
  return String(content == null ? "" : content);
}

function openaiError(status, message, type) {
  const err = new Error(message);
  err.status = status;
  err.openaiType = type || (status === 400 ? "invalid_request_error" : "server_error");
  return err;
}

function buildPromptText(messages, maxChars) {
  const limit = maxChars || MAX_PROMPT_CHARS;
  if (!Array.isArray(messages) || messages.length === 0) {
    throw openaiError(400, "messages array is required and must not be empty", "invalid_request_error");
  }
  let system = "";
  const turns = [];
  for (const m of messages) {
    const role = (m && m.role) || "user";
    const text = extractTextContent(m && m.content).trim();
    if (!text) continue;
    if (role === "system") system += (system ? "\n" : "") + text;
    else if (role === "assistant") turns.push({ who: "Assistant", text: text });
    else if (role === "tool" || role === "function") turns.push({ who: "Tool result", text: text });
    else turns.push({ who: "User", text: text });
  }
  if (turns.length === 0) throw openaiError(400, "no usable message content found", "invalid_request_error");
  const block = function () {
    return turns.map(function (t) { return t.who + ": " + t.text; }).join("\n\n");
  };
  while (turns.length > 1 && (system.length + block().length) > limit) turns.shift();
  let prompt = (system ? "System: " + system + "\n\n" : "") + block();
  if (prompt.length > limit) prompt = prompt.slice(prompt.length - limit);
  return prompt;
}

function chartToText(ev) {
  const lines = [];
  lines.push("[chart" + (ev.title ? ": " + ev.title : "") + "]");
  try {
    const opt = ev.option || {};
    const cats = (opt.xAxis && opt.xAxis.data) || [];
    const series = (opt.series && opt.series[0]) || {};
    const vals = series.data || [];
    if (cats.length && vals.length) {
      lines.push(cats.join(" | "));
      lines.push(vals.map(function (v) { return String(v); }).join(" | "));
    } else {
      lines.push(JSON.stringify(opt).slice(0, 1000));
    }
  } catch (err) {
    lines.push("(chart data unavailable)");
  }
  return lines.join("\n");
}

function newCompletionId() {
  const hex = "0123456789abcdef";
  let s = "";
  const rnd = new Uint8Array(12);
  crypto.getRandomValues(rnd);
  for (let i = 0; i < 12; i++) s += hex[rnd[i] & 15] + hex[(rnd[i] >> 4) & 15];
  return "chatcmpl-askme-" + s;
}

function openaiChunk(id, model, delta, finishReason) {
  return "data: " + JSON.stringify({
    id: id,
    object: "chat.completion.chunk",
    created: Math.floor(Date.now() / 1000),
    model: model,
    choices: [{ index: 0, delta: delta, finish_reason: finishReason || null }]
  });
}

// ------------- DeepSeek PoW: bundled WASM solver (base64) -------------------
// DeepSeekHashV1 uses a NON-STANDARD hash (plain SHA3-256 does NOT match), so
// this file embeds DeepSeek's own solver module (sha3_wasm_bg.wasm, from
// https://fe-static.deepseek.com/chat/) as base64 and drives wasm_solve()
// directly. Verified live: difficulty-144000 challenges solve in well under
// a second on a real CPU. The placeholder below is filled at build time
// (see README); DO NOT hand-edit the base64.
const DS_WASM_B64 = "";
let dsWasmCache = null;
async function dsWasm() {
  if (dsWasmCache) return dsWasmCache;
  const bin = atob(DS_WASM_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  dsWasmCache = (await WebAssembly.instantiate(bytes)).instance.exports;
  return dsWasmCache;
}

async function dsWasmSolve(challengeHex, prefix, limit) {
  // Returns the PoW answer (number) or null when unsolvable.
  const wasm = await dsWasm();
  const malloc = wasm.__wbindgen_export_0;
  const mem = function () { return new Uint8Array(wasm.memory.buffer); };
  const view = function () { return new DataView(wasm.memory.buffer); };
  const writeStr = function (s) {
    const b = new TextEncoder().encode(s);
    const ptr = malloc(b.length, 1) >>> 0;
    mem().set(b, ptr);
    return [ptr, b.length];
  };
  const cp = writeStr(challengeHex);
  const pp = writeStr(prefix);
  const rp = malloc(64, 1) >>> 0;
  wasm.wasm_solve(rp, cp[0], cp[1], pp[0], pp[1], limit);
  if (view().getInt32(rp, true) === 0) return null;
  return view().getFloat64(rp + 8, true);
}

// --------------------------- AskMe backend ---------------------------------
let askmeServerTimeOffsetMs = 0;
let askmeDeviceId = null;

async function aSha256(bytes) {
  return new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
}

async function aHmac(key64, data) {
  const key = await crypto.subtle.importKey("raw", key64, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return new Uint8Array(await crypto.subtle.sign("HMAC", key, data));
}

function b64urlNoPad(bytes) {
  let bin = "";
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function bWQ(a, g) {
  let q = (1095977805 ^ (g & 65535)) >>> 0;
  for (let r = 0; r < a.length; r++) {
    const factor = (((g >>> ((r * 3) % 32)) & 7) + 1);
    q = (((q << 5) >>> 0) + q * factor + a[r]) >>> 0;
  }
  return (q ^ 1161906481 ^ ((g >>> 16) & 65535)) >>> 0;
}

function bWPConcat(g) {
  const h = [];
  for (let qi = 0; qi < 8; qi++) {
    const p = (((g >>> (qi * 4)) & 15) + 1);
    const suf = SUFFIXES[qi];
    for (let k = 0; k < suf.length; k++) h.push((((suf.charCodeAt(k) ^ 90) * p) & 255));
  }
  const m = [];
  for (let q = 7; q >= 0; q--) m.push(Math.floor(g / Math.pow(256, q)) & 255);
  return h.concat(m);
}

function bUv(a, seed) {
  let s = seed;
  const q = new Array(a.length);
  for (let r = 0; r < a.length; r++) {
    const mod = r % 4;
    if (mod === 0) q[r] = (a[r] ^ ((r * 7 + 13) & 255) ^ (s & 255)) & 255;
    else if (mod === 1) q[r] = ((a[r] + ((r * 11 + 17) & 255) - (s & 63)) & 255);
    else if (mod === 2) q[r] = (a[r] ^ ((r * 13 + 23) & 255) ^ ((s >>> 2) & 15)) & 255;
    else q[r] = ((a[r] - ((r * 17 + 31) & 127) + ((s >>> 4) & 31)) & 255);
    s = (((Math.imul(s, 1103515245) + 12345) >>> 0) >>> 16) & 0x7FFF;
  }
  return q;
}

function aMakeRand16(h) {
  const rnd = new Uint8Array(16);
  crypto.getRandomValues(rnd);
  const hour = Math.floor(h / 3600000) % 24;
  const minute = Math.floor(h / 60000) % 60;
  const t = ((hour * 60 + minute) ^ 43981) & 255;
  const e = new Uint8Array(16);
  for (let i = 0; i < 16; i++) e[i] = (i % 4 === 0) ? ((rnd[i] ^ t) & 255) : rnd[i];
  return e;
}

async function askmeGenToken(deviceId, nowMs) {
  const h = nowMs;
  const g = Math.floor(h / 300000);
  const e = aMakeRand16(h);
  const d = new TextEncoder().encode(deviceId);
  const b = [];
  for (let s = 7; s >= 0; s--) b.push(Math.floor(g / Math.pow(256, s)) & 255);
  b.push(d.length & 255);
  for (const x of d) b.push(x);
  for (const x of e) b.push(x);
  const r = bWQ(b, g);
  for (let s = 3; s >= 0; s--) b.push((r >>> (s * 8)) & 255);

  const sConcat = bWPConcat(g);
  const l = await aSha256(new Uint8Array(sConcat));
  const k = [];
  for (let i = 0; i < l.length; i++) {
    const sb = l[i], ri = i % 8, o = BCG[ri], n = AUW[ri];
    k.push((((((sb ^ o) >>> 0) + (o & n) - (sb | n)) & 255) ^ AS0[ri]) & 255);
  }
  const p64 = new Uint8Array(64);
  p64.set(k.slice(0, 64));
  const nHmac = await aHmac(p64, new Uint8Array(b));

  const p0 = e[0];
  const mVal = ((g & 65535) ^ p0) & 0xFFFF;
  const lVal = (((g >>> 16) & 65535) ^ (p0 >>> 8)) & 0xFFFF;
  const pList = Array.from(nHmac);
  pList.push((mVal >>> 8) & 255, mVal & 255, (lVal >>> 8) & 255, lVal & 255);
  const kHash = await aSha256(new Uint8Array(pList));

  const j = [];
  for (let s = 0; s < 32; s++) j.push((s % 2 === 0) ? nHmac[s] : kHash[s]);
  const f = b.concat(j);
  const seed = (Math.floor(g * 31337) & 0x7FFFFFFF);
  return b64urlNoPad(bUv(f, seed));
}

function parseAskmeBlock(block) {
  const events = [];
  for (const line of block.split("\n")) {
    const t = line.trim();
    if (!t.startsWith("data:")) continue;
    const payload = t.slice(5).trim();
    if (!payload) continue;
    try {
      events.push(JSON.parse(payload));
    } catch (err) { /* ignore */ }
  }
  return events;
}

async function askmeFetch(prompt, askmeOrigin, token, signal) {
  return await fetch(askmeOrigin + "/api/chat/stream", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Cache-Control": "no-cache",
      "Accept": "text/event-stream",
      "X-App-Token": token,
      "X-App-Version": APP_VERSION,
      "X-AskMe-Streaming-Protocol": "1",
      "X-AskMe-Visualization-Protocol": "1",
      "X-AskMe-Music-Protocol": "1"
    },
    body: JSON.stringify({
      message: prompt,
      deviceId: askmeDeviceId,
      utcOffsetMinutes: -new Date().getTimezoneOffset()
    }),
    signal: signal
  });
}

async function askmeStream(prompt, askmeOrigin, onEvent, signal) {
  if (!askmeDeviceId) {
    const rnd = new Uint8Array(16);
    crypto.getRandomValues(rnd);
    rnd[6] = (rnd[6] & 15) | 64;
    rnd[8] = (rnd[8] & 63) | 128;
    const hex = Array.from(rnd).map(function (b) { return b.toString(16).padStart(2, "0"); }).join("");
    askmeDeviceId = hex.slice(0, 8) + "-" + hex.slice(8, 12) + "-" + hex.slice(12, 16) + "-" + hex.slice(16, 20) + "-" + hex.slice(20);
  }
  let res = await askmeFetch(prompt, askmeOrigin, await askmeGenToken(askmeDeviceId, Date.now() + askmeServerTimeOffsetMs), signal);
  if (res.status === 401) {
    let serverTime = null;
    try {
      const j = JSON.parse(await res.text());
      if (j && j.serverTime) serverTime = j.serverTime;
    } catch (err) { /* ignore */ }
    if (!serverTime) throw openaiError(502, "AskMe rejected the request (unauthorized)", "server_error");
    askmeServerTimeOffsetMs = serverTime - Date.now();
    res = await askmeFetch(prompt, askmeOrigin, await askmeGenToken(askmeDeviceId, serverTime), signal);
    if (res.status === 401) throw openaiError(502, "AskMe rejected the request (unauthorized)", "server_error");
  }
  if (!res.ok || !res.body) {
    const txt = await res.text().catch(function () { return ""; });
    throw openaiError(502, "AskMe request failed (HTTP " + res.status + "): " + String(txt).slice(0, 200), "server_error");
  }
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buf = "";
  for (;;) {
    const step = await reader.read();
    if (step.done) break;
    buf += decoder.decode(step.value, { stream: true });
    let idx;
    while ((idx = buf.indexOf("\n\n")) >= 0) {
      const block = buf.slice(0, idx);
      buf = buf.slice(idx + 2);
      for (const ev of parseAskmeBlock(block)) onEvent(ev);
    }
  }
  buf += decoder.decode();
  if (buf.trim()) {
    for (const ev of parseAskmeBlock(buf)) onEvent(ev);
  }
}

// -------------------------- DeepSeek backend -------------------------------
function dsNeedToken(dsToken) {
  if (!dsToken) {
    throw openaiError(400, "DeepSeek backend needs DEEPSEEK_TOKEN (your chat.deepseek.com login `userToken`). Set it and redeploy.", "invalid_request_error");
  }
}

function dsStableDeviceId(token) {
  // Deterministic device id per token (a real client keeps one for life;
  // random-per-deploy is a bot tell). Sync FNV-1a hash — stability is all
  // that matters here, not cryptographic strength.
  let h1 = 0x811c9dc5, h2 = 0x01000193, h3 = 0xdeadbeef, h4 = 0x41c6ce57;
  const s = "ds-device|" + (token || "");
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619);
    h2 = Math.imul(h2 ^ (c + 31), 2246822519);
    h3 = Math.imul(h3 ^ (c * 3 + 7), 3266489917);
    h4 = Math.imul(h4 ^ (c + 11), 668265263);
  }
  const hex = function (h) { return (h >>> 0).toString(16).padStart(8, "0"); };
  const h = hex(h1) + hex(h2) + hex(h3) + hex(h4);
  return h.slice(0, 8) + "-" + h.slice(8, 12) + "-4" + h.slice(13, 16) + "-a" + h.slice(17, 20) + "-" + h.slice(20, 32);
}

// Per-isolate runtime config (set from env on each fetch) + session cache.
// Note: isolates are recycled, so session reuse is best-effort here — still
// far less fresh-session-per-request churn than before.
let DS_CFG = { reuseMs: 20 * 60 * 1000, delayMs: 800 };
let dsSessionCache = { id: null, at: 0 };
function dsEnvMs(env, name, def) {
  const v = env && env[name];
  if (v == null || v === "") return def;
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : def;
}
function dsSleep(ms) { return new Promise(function (res) { setTimeout(res, ms); }); }
async function dsHumanPause() {
  if (!(DS_CFG.delayMs > 0)) return;
  await dsSleep(150 + Math.random() * DS_CFG.delayMs);
}

function dsHeaders(dsToken, extra) {
  dsNeedToken(dsToken);
  // The web client sends these on every API call; /chat/completion answers
  // 40300 MISSING_HEADER without them (verified live).
  return Object.assign({
    "Content-Type": "application/json",
    "Accept": "*/*",
    "Origin": "https://chat.deepseek.com",
    "Referer": "https://chat.deepseek.com/",
    "Authorization": "Bearer " + dsToken,
    "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36",
    "x-device-id": dsStableDeviceId(dsToken),
    "x-device-model": "Chrome",
    "x-client-bundle-id": "com.deepseek.chat",
    "x-client-platform": "web",
    "x-client-version": "1.0.0",
    "x-client-locale": "en_US",
    "x-client-timezone-offset": "0"
  }, extra || {});
}

async function dsPost(dsOrigin, dsToken, path, body, timeoutMs) {
  const ctl = new AbortController();
  const timer = setTimeout(function () { ctl.abort(); }, timeoutMs || 30000);
  try {
    const res = await fetch(dsOrigin + path, {
      method: "POST",
      headers: dsHeaders(dsToken),
      body: JSON.stringify(body == null ? {} : body),
      signal: ctl.signal
    });
    const text = await res.text();
    let json = null;
    try { json = JSON.parse(text); } catch (err) { /* keep null */ }
    return { status: res.status, json: json, text: text };
  } finally {
    clearTimeout(timer);
  }
}

function dsCheckBiz(json, what) {
  if (!json || typeof json.code !== "undefined") {
    const code = json && json.code;
    if (code === 40003 || code === 401) throw openaiError(502, "DeepSeek rejected the login token (INVALID_TOKEN). Set a fresh `userToken` as DEEPSEEK_TOKEN.", "server_error");
    if (code !== 0 && code != null) throw openaiError(502, "DeepSeek " + what + " failed: code=" + code + " msg=" + ((json && json.msg) || "?"), "server_error");
  }
  const data = json && json.data;
  if (data && typeof data.biz_code !== "undefined" && data.biz_code !== 0) {
    throw openaiError(502, "DeepSeek " + what + " failed: biz_code=" + data.biz_code + " biz_msg=" + (data.biz_msg || "?"), "server_error");
  }
  return data && data.biz_data;
}

// Solve DeepSeekHashV1 via the bundled WASM (see above). Returns
// {answer} or null (the server occasionally hands out unsolvable
// challenges — caller refetches).
async function dsSolvePow(challenge) {
  const prefix = challenge.salt + "_" + challenge.expireAt + "_";
  const target = challenge.challenge;
  const limit = Number(challenge.difficulty);
  if (!challenge.salt || !target || !(limit > 0) || limit > 1e9) return null;
  const ans = await dsWasmSolve(target, prefix, limit);
  if (ans == null) return null;
  return { answer: ans };
}

async function dsPowHeader(dsOrigin, dsToken) {
  // Up to 5 fetch+solve rounds: unsolvable challenges are discarded and
  // refetched (issuance is reliable, so repeated misses mean real trouble).
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      const r = await dsPost(dsOrigin, dsToken, "/api/v0/chat/create_pow_challenge", { target_path: DS_TARGET_PATH });
      const biz = dsCheckBiz(r.json, "create_pow_challenge");
      const c = (biz && biz.challenge) || biz || {};
      const challenge = {
        algorithm: c.algorithm || "DeepSeekHashV1",
        challenge: c.challenge,
        salt: c.salt,
        difficulty: c.difficulty,
        signature: c.signature,
        expireAt: c.expire_at != null ? c.expire_at : c.expireAt
      };
      if (!challenge.challenge || !challenge.salt) return {};
      const sol = await dsSolvePow(challenge);
      if (sol == null) {
        // Back off before refetching: hammering challenge fetches looks automated.
        await dsSleep(attempt * 600 + Math.random() * 500);
        continue;
      }
      let bin = JSON.stringify({
        algorithm: challenge.algorithm,
        challenge: challenge.challenge,
        salt: challenge.salt,
        answer: sol.answer,
        signature: challenge.signature,
        target_path: DS_TARGET_PATH
      });
      let b64 = "";
      const bytes = new TextEncoder().encode(bin);
      let s = "";
      for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
      b64 = btoa(s);
      return { "X-DS-PoW-Response": b64 };
    } catch (err) {
      return {};
    }
  }
  return {};
}

function dsParseSseBlock(block) {
  const out = [];
  let event = "message";
  const datas = [];
  const flush = function () {
    if (datas.length) {
      const raw = datas.join("\n");
      let data = raw;
      try { data = JSON.parse(raw); } catch (err) { /* keep raw */ }
      out.push({ event: event, data: data });
    }
    event = "message";
    datas.length = 0;
  };
  for (const line of block.split("\n")) {
    const t = line.trim();
    if (!t) { flush(); continue; }
    if (t.startsWith("event:")) { event = t.slice(6).trim(); }
    else if (t.startsWith("data:")) { datas.push(t.slice(5).trim()); }
  }
  flush();
  return out;
}

// Live text from the real DeepSeek SSE shapes (captured live — the stream has
// NO "delta" events; text arrives as data blocks in these shapes):
// - full snapshot: {v:{response:{fragments:[{type:"RESPONSE",content:"..."}]}}}
// - content append: {o:"APPEND", p:".../content", v:"..."}
// - bare token:     {v:"..."}  (no o/p — the common per-chunk shape)
// Returns true when the block signals completion. `refs` (optional array)
// collects web-search result entries {cite_index,title,url} from
// {p:".../results", v:[...]} blocks for a Sources section.
function dsStreamText(data, sink, refs) {
  let finished = false;
  // `top` = this object is a whole data block (not nested inside a BATCH):
  // only a top-level bare {v:"..."} is a text token. BATCH children carry
  // metadata (token usage, quasi_status) whose bare strings must be ignored.
  const walk = function (d, top) {
    if (!d || typeof d !== "object") return;
    if (typeof d.p === "string" && /results/i.test(d.p) && Array.isArray(d.v)) {
      if (refs) {
        for (const r of d.v) {
          if (r && typeof r.url === "string" && r.url) {
            refs.push({ cite_index: r.cite_index, title: String(r.title || r.url), url: r.url });
          }
        }
      }
      return;
    }
    if (typeof d.o === "string") {
      if (d.o === "BATCH" && Array.isArray(d.v)) { for (const x of d.v) walk(x, false); return; }
      if (d.o === "SET" && d.p === "response/status" && d.v === "FINISHED") { finished = true; return; }
      if (d.o === "APPEND" && typeof d.v === "string" &&
          typeof d.p === "string" && /content/i.test(d.p)) { sink(d.v); return; }
      return;
    }
    if (top && typeof d.v === "string") { sink(d.v); return; }
    const resp = d.v && d.v.response;
    if (resp && Array.isArray(resp.fragments)) {
      for (const f of resp.fragments) {
        if (f && f.type === "RESPONSE" && typeof f.content === "string" && f.content) sink(f.content);
      }
    }
  };
  walk(data, true);
  return finished;
}

async function dsFetchHistoryText(dsOrigin, dsToken, sessionId) {
  try {
    const ctl = new AbortController();
    const timer = setTimeout(function () { ctl.abort(); }, 30000);
    let res;
    try {
      res = await fetch(dsOrigin + "/api/v0/chat/history_messages?chat_session_id=" + encodeURIComponent(sessionId), {
        headers: dsHeaders(dsToken, { Accept: "application/json" }),
        signal: ctl.signal
      });
    } finally {
      clearTimeout(timer);
    }
    const json = await res.json().catch(function () { return null; });
    const biz = dsCheckBiz(json, "history_messages");
    const msgs = (biz && (biz.messages || biz.history_messages || biz.chat_messages)) || [];
    for (let i = msgs.length - 1; i >= 0; i--) {
      const m = msgs[i] || {};
      const role = String(m.role || m.message_role || "").toUpperCase();
      if (role && role !== "ASSISTANT" && role !== "AI") continue;
      const frags = m.fragments || m.fragment || [];
      const parts = [];
      for (const f of frags) {
        // Only real answer text: skip the user's echo, the search-status
        // fragment ("Found N web pages") and reasoning traces.
        const t = String((f && (f.fragmentType || f.fragment_type || f.type)) || "").toUpperCase();
        if (t === "THINK" || t === "THINKING" || t === "SEARCH" || t === "REQUEST") continue;
        const c = f && (f.content != null ? f.content : f.text);
        if (typeof c === "string" && c) parts.push(c);
      }
      if (parts.length) return parts.join("");
      if (typeof m.content === "string" && m.content) return m.content;
    }
    return "";
  } catch (err) {
    return "";
  }
}

async function dsSessionId(dsOrigin, dsToken) {
  // Reuse one chat session for a while, like a human keeping a tab open,
  // instead of a fresh single-shot session per request (a bot tell).
  if (dsSessionCache.id && (Date.now() - dsSessionCache.at) < DS_CFG.reuseMs) return dsSessionCache.id;
  const s = await dsPost(dsOrigin, dsToken, "/api/v0/chat_session/create", {});
  const sBiz = dsCheckBiz(s.json, "chat_session/create");
  const session = (sBiz && sBiz.chat_session) || sBiz || {};
  const sessionId = session.id || session.chat_session_id;
  if (!sessionId) throw openaiError(502, "DeepSeek session create gave no id.", "server_error");
  dsSessionCache = { id: sessionId, at: Date.now() };
  return sessionId;
}

async function deepseekTurn(prompt, dsOrigin, dsToken, onText, signal, search) {
  // Small random pause so request cadence stops looking mechanical.
  await dsHumanPause();
  const sessionId = await dsSessionId(dsOrigin, dsToken);

  const powHeaders = await dsPowHeader(dsOrigin, dsToken);

  const ctl = new AbortController();
  const timer = setTimeout(function () { ctl.abort(); }, DS_TIMEOUT_MS);
  const onAbort = function () { ctl.abort(); };
  if (signal) {
    if (signal.aborted) ctl.abort();
    else signal.addEventListener("abort", onAbort, { once: true });
  }
  let streamed = "";
  const refs = [];
  try {
    const res = await fetch(dsOrigin + DS_TARGET_PATH, {
      method: "POST",
      headers: dsHeaders(dsToken, Object.assign({ Accept: "text/event-stream" }, powHeaders)),
      body: JSON.stringify({
        chat_session_id: sessionId,
        parent_message_id: null,
        model_type: DS_MODEL_TYPE,
        prompt: prompt,
        ref_file_ids: [],
        thinking_enabled: false,
        search_enabled: !!search,
        action: null,
        preempt: false
      }),
      signal: ctl.signal
    });
    const ctype = (res.headers.get("content-type") || "").toLowerCase();
    if (!res.ok || !res.body || ctype.includes("application/json")) {
      const txt = await res.text().catch(function () { return ""; });
      if (/40300|MISSING_HEADER/.test(txt)) {
        throw openaiError(502, "DeepSeek completion rejected (40300 MISSING_HEADER): the gateway reached DeepSeek but DeepSeek says required headers/PoW are missing. Likely causes: (1) old Worker code without device headers — re-paste the latest askme-cloudflare-worker.mjs and redeploy; (2) Cloudflare free plan — DeepSeek PoW needs ~0.5s CPU, use the local Node gateway or a paid plan (AskMe works on free); (3) PoW solve failed. Raw: " + String(txt).slice(0, 200), "server_error");
      }
      throw openaiError(502, "DeepSeek completion failed (HTTP " + res.status + "): " + String(txt).slice(0, 300), "server_error");
    }
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    let finished = false;
    for (;;) {
      const step = await reader.read();
      if (step.done) break;
      buf += decoder.decode(step.value, { stream: true });
      let idx;
      while ((idx = buf.indexOf("\n\n")) >= 0) {
        const block = buf.slice(0, idx);
        buf = buf.slice(idx + 2);
        for (const ev of dsParseSseBlock(block)) {
          if (ev.event === "close") {
            finished = true;
          } else if (typeof ev.data !== "undefined") {
            if (dsStreamText(ev.data, function (chunk) {
              streamed += chunk;
              onText(chunk);
            }, refs)) finished = true;
          }
        }
      }
      if (finished) break;
    }
    try { await reader.cancel(); } catch (err) { /* ignore */ }
  } finally {
    clearTimeout(timer);
    if (signal) signal.removeEventListener("abort", onAbort);
  }

  const full = await dsFetchHistoryText(dsOrigin, dsToken, sessionId);
  let text;
  if (full) {
    if (!streamed) text = full;
    else if (full.startsWith(streamed)) {
      const tail = full.slice(streamed.length);
      if (tail) onText(tail);
      text = full;
    } else if (streamed.startsWith(full)) text = streamed;
    else text = full;
  } else {
    text = streamed;
  }
  const sources = dsSourcesSection(refs);
  if (sources) {
    onText(sources);
    text += sources;
  }
  return text;
}

function dsSourcesSection(refs) {
  const seen = new Set();
  const items = [];
  for (const r of refs || []) {
    const n = Number(r && r.cite_index);
    const key = (Number.isFinite(n) ? n : 0) + "|" + (r && r.url);
    if (!r || !r.url || seen.has(key)) continue;
    seen.add(key);
    items.push({ n: Number.isFinite(n) ? n : 1e9, title: String((r && r.title) || r.url), url: r.url });
    if (items.length >= 40) break;
  }
  if (!items.length) return "";
  items.sort(function (a, b) { return a.n - b.n; });
  const top = items.slice(0, 10);
  return "\n\nSources:\n" + top.map(function (r) {
    return "[" + (r.n > 1e8 ? "?" : r.n) + "] " + r.title + " — " + r.url;
  }).join("\n");
}

// ------------------------------ handlers -----------------------------------
function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
    "Access-Control-Max-Age": "86400"
  };
}

function jsonResponse(obj, status) {
  return new Response(JSON.stringify(obj), {
    status: status || 200,
    headers: Object.assign({ "Content-Type": "application/json" }, corsHeaders())
  });
}

function errorResponse(err) {
  const status = (err && err.status) || 500;
  return jsonResponse({
    error: {
      message: String((err && err.message) || "unknown error"),
      type: String((err && err.openaiType) || "server_error"),
      code: status
    }
  }, status);
}

function checkAuth(request, apiKey) {
  if (!apiKey) return;
  const hdr = request.headers.get("authorization") || "";
  if (hdr !== "Bearer " + apiKey) throw openaiError(401, "invalid API key", "invalid_request_error");
}

function isDeepSeekModel(model, dsModelId) {
  return model === dsModelId || /^deepseek/i.test(model || "");
}

export default {
  async fetch(request, env) {
    const modelId = (env && env.MODEL_ID) || "askme-ai";
    const dsModelId = (env && env.DS_MODEL_ID) || "deepseek";
    const dsSearchModelId = (env && env.DS_SEARCH_MODEL_ID) || "deepseek-search";
    const apiKey = (env && env.API_KEY) || "";
    const askmeOrigin = ((env && env.ASKME_ORIGIN) || "https://www.ask-me-ai.app").replace(/\/+$/, "");
    const dsOrigin = ((env && env.DS_ORIGIN) || "https://chat.deepseek.com").replace(/\/+$/, "");
    const dsToken = (env && env.DEEPSEEK_TOKEN) || "";
    DS_CFG = {
      reuseMs: dsEnvMs(env, "DS_SESSION_REUSE_MS", 20 * 60 * 1000),
      delayMs: dsEnvMs(env, "DS_HUMAN_DELAY_MS", 800)
    };

    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: corsHeaders() });
    }
    try {
      const url = new URL(request.url);
      const path = (url.pathname.replace(/\/+$/, "") || "/");

      if (request.method === "GET" && (path === "/" || path === "/healthz")) {
        return jsonResponse({ ok: true, name: "askme-deepseek-gateway", models: [modelId, dsModelId], endpoints: ["GET /v1/models", "POST /v1/chat/completions"] });
      }
      if (request.method === "GET" && (path === "/v1/models" || path === "/models")) {
        checkAuth(request, apiKey);
        const list = [{ id: modelId, object: "model", created: Math.floor(Date.now() / 1000), owned_by: "askme-bridge" }];
        if (dsModelId && dsModelId !== modelId) {
          list.push({ id: dsModelId, object: "model", created: Math.floor(Date.now() / 1000), owned_by: "deepseek-bridge" });
        }
        if (dsSearchModelId && dsSearchModelId !== modelId && dsSearchModelId !== dsModelId) {
          list.push({ id: dsSearchModelId, object: "model", created: Math.floor(Date.now() / 1000), owned_by: "deepseek-bridge" });
        }
        return jsonResponse({ object: "list", data: list });
      }
      if (request.method === "POST" && (path === "/v1/chat/completions" || path === "/chat/completions")) {
        checkAuth(request, apiKey);
        let payload;
        try {
          payload = await request.json();
        } catch (err) {
          throw openaiError(400, "invalid JSON body", "invalid_request_error");
        }
        const model = payload.model || modelId;
        const stream = !!payload.stream;
        const prompt = buildPromptText(payload.messages, MAX_PROMPT_CHARS);
        const promptTokens = estimateTokens(prompt);
        const id = newCompletionId();
        const useDS = isDeepSeekModel(model, dsModelId);
        const useSearch = model === dsSearchModelId;

        const ctl = new AbortController();
        const timer = setTimeout(function () { ctl.abort(); }, DS_TIMEOUT_MS);
        try {
          if (!stream) {
            let text = "";
            if (useDS) {
              text = await deepseekTurn(prompt, dsOrigin, dsToken, function () {}, ctl.signal, useSearch);
            } else {
              await askmeStream(prompt, askmeOrigin, function (ev) {
                if (ev && ev.type === "text" && typeof ev.content === "string") text += ev.content;
                else if (ev && ev.type === "chart") text += (text ? "\n" : "") + chartToText(ev);
              }, ctl.signal);
            }
            const ct = estimateTokens(text);
            return jsonResponse({
              id: id,
              object: "chat.completion",
              created: Math.floor(Date.now() / 1000),
              model: model,
              choices: [{ index: 0, message: { role: "assistant", content: text }, finish_reason: "stop" }],
              usage: { prompt_tokens: promptTokens, completion_tokens: ct, total_tokens: promptTokens + ct }
            });
          }

          let upstream;
          if (useDS) {
            const { readable, writable } = new TransformStream();
            const writer = writable.getWriter();
            const enc = new TextEncoder();
            const send = function (line) { writer.write(enc.encode(line + "\n\n")); };
            send(openaiChunk(id, model, { role: "assistant" }, null));
            deepseekTurn(prompt, dsOrigin, dsToken, function (chunk) {
              if (chunk) send(openaiChunk(id, model, { content: chunk }, null));
            }, ctl.signal, useSearch).then(function () {
              send(openaiChunk(id, model, {}, "stop"));
              writer.write(enc.encode("data: [DONE]\n\n"));
              writer.close();
            }, function () {
              try { writer.close(); } catch (e2) { /* ignore */ }
            });
            upstream = readable;
          } else {
            const askmeRes = await (async function () {
              // Bridge AskMe SSE -> OpenAI SSE via TransformStream.
              const { readable, writable } = new TransformStream();
              const writer = writable.getWriter();
              const enc = new TextEncoder();
              const send = function (line) { writer.write(enc.encode(line + "\n\n")); };
              send(openaiChunk(id, model, { role: "assistant" }, null));
              askmeStream(prompt, askmeOrigin, function (ev) {
                if (ev && ev.type === "text" && typeof ev.content === "string" && ev.content) {
                  send(openaiChunk(id, model, { content: ev.content }, null));
                } else if (ev && ev.type === "chart") {
                  send(openaiChunk(id, model, { content: "\n" + chartToText(ev) }, null));
                }
              }, ctl.signal).then(function () {
                send(openaiChunk(id, model, {}, "stop"));
                writer.write(enc.encode("data: [DONE]\n\n"));
                writer.close();
              }, function () {
                try { writer.close(); } catch (e2) { /* ignore */ }
              });
              return readable;
            })();
            upstream = askmeRes;
          }
          return new Response(upstream, {
            headers: Object.assign({
              "Content-Type": "text/event-stream",
              "Cache-Control": "no-cache",
              "Connection": "keep-alive"
            }, corsHeaders())
          });
        } finally {
          clearTimeout(timer);
        }
      }
      return jsonResponse({ error: { message: "not found: " + path, type: "invalid_request_error", code: 404 } }, 404);
    } catch (err) {
      return errorResponse(err);
    }
  }
};
